const ex = nodes.extract.output;
const baseDateRaw = input.meeting_date;
let base;
if (baseDateRaw && /^\d{4}-\d{2}-\d{2}$/.test(baseDateRaw)) {
  base = new Date(baseDateRaw + 'T00:00:00Z');
} else {
  base = new Date();
  base = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth(), base.getUTCDate()));
}
function iso(d) { return d.toISOString().slice(0, 10); }
function addDays(n) { const d = new Date(base); d.setUTCDate(d.getUTCDate() + n); return d; }
const DAYS = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
const WORDNUM = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, a: 1, an: 1, couple: 2, few: 3 };
function num(tok) {
  if (!tok) return null;
  const t = tok.toLowerCase().trim();
  if (/^\d+$/.test(t)) return parseInt(t, 10);
  return WORDNUM[t] !== undefined ? WORDNUM[t] : null;
}
function resolveDate(raw) {
  if (!raw || typeof raw !== 'string') return null;
  const s = raw.trim().toLowerCase();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const mIso = s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (mIso) return mIso[1] + '-' + String(mIso[2]).padStart(2, '0') + '-' + String(mIso[3]).padStart(2, '0');
  let m = s.match(/(?:next|this|coming)?\s*(monday|tuesday|wednesday|thursday|friday|saturday|sunday)/);
  if (m) {
    const target = DAYS[m[1]];
    let diff = (target - base.getUTCDay() + 7) % 7;
    if (diff === 0) diff = 7;
    return iso(addDays(diff));
  }
  if (/tomorrow/.test(s)) return iso(addDays(1));
  if (/today|eod|end of day/.test(s)) return iso(base);
  m = s.match(/in\s+([a-z\d]+)\s+days?/);
  if (m) { const n = num(m[1]); if (n !== null) return iso(addDays(n)); }
  m = s.match(/in\s+([a-z\d]+)\s+weeks?/);
  if (m) { const n = num(m[1]); if (n !== null) return iso(addDays(n * 7)); }
  if (/next week/.test(s)) return iso(addDays(7));
  m = s.match(/in\s+([a-z\d]+)\s+months?/);
  if (m) { const n = num(m[1]); if (n !== null) { const d = new Date(base); d.setUTCMonth(d.getUTCMonth() + n); return iso(d); } }
  if (/end of (the )?month/.test(s)) {
    const d = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth() + 1, 0));
    return iso(d);
  }
  if (/end of (the )?quarter/.test(s)) {
    const q = Math.floor(base.getUTCMonth() / 3);
    const d = new Date(Date.UTC(base.getUTCFullYear(), (q + 1) * 3, 0));
    return iso(d);
  }
  const MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december'];
  m = s.match(/(january|february|march|april|may|june|july|august|september|october|november|december)\s+(\d{1,2})/);
  if (m) {
    const mo = MONTHS.indexOf(m[1]);
    let year = base.getUTCFullYear();
    if (mo < base.getUTCMonth()) year += 1;
    return year + '-' + String(mo + 1).padStart(2, '0') + '-' + String(parseInt(m[2], 10)).padStart(2, '0');
  }
  m = s.match(/(\d{1,2})\s+(january|february|march|april|may|june|july|august|september|october|november|december)/);
  if (m) {
    const mo = MONTHS.indexOf(m[2]);
    let year = base.getUTCFullYear();
    if (mo < base.getUTCMonth()) year += 1;
    return year + '-' + String(mo + 1).padStart(2, '0') + '-' + String(parseInt(m[1], 10)).padStart(2, '0');
  }
  return null;
}
function norm(s) { return (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim(); }
function dedupe(list, keyFn) {
  const seen = new Set();
  const out = [];
  for (const item of list) {
    const k = norm(keyFn(item));
    if (!k || seen.has(k)) continue;
    seen.add(k);
    out.push(item);
  }
  return out;
}
const decisions = dedupe(Array.isArray(ex.decisions) ? ex.decisions : [], d => d.decision)
  .map(d => ({ decision: (d.decision || '').trim(), context: (d.context || '').trim() }));
const seenTasks = new Set();
const action_items = [];
for (const ai of (Array.isArray(ex.action_items) ? ex.action_items : [])) {
  const task = (ai.task || '').trim();
  const k = norm(task);
  if (!k || seenTasks.has(k)) continue;
  seenTasks.add(k);
  const owner = (ai.owner === null || ai.owner === undefined || ai.owner === '') ? null : String(ai.owner).trim();
  action_items.push({
    task: task,
    owner: owner,
    due_date: resolveDate(ai.due_date_raw),
    owner_missing: owner === null
  });
}
return { decisions: decisions, action_items: action_items, resolved_dates: action_items.map(a => a.due_date).filter(Boolean) };

